Deno.test('handler: POST /requisicao com itens_invalidos da RPC → 422', async () => {
  // RPC retorna ok=false com itens_invalidos quando produto_master_id não existe/inativo
  const mockComItensInvalidos = {
    rpc: (name: string) => {
      if (name === 'validar_pdv_api_key') {
        return Promise.resolve({
          data: { ok: true, api_key_id: 'uuid-abc', loja_ids: [2] },
          error: null,
        })
      }
      if (name === 'criar_requisicao_pdv') {
        return Promise.resolve({
          data: {
            ok: false,
            erro: 'produto_master_id inválido(s) ou inativo(s)',
            itens_invalidos: [9999, 8888],
          },
          error: null,
        })
      }
      return Promise.resolve({ data: null, error: null })
    },
  }
  const req = new Request(
    'https://proj.supabase.co/functions/v1/pdv-movimentacao/requisicao',
    {
      method: 'POST',
      headers: { 'x-api-key': 'pdvk_teste', 'Content-Type': 'application/json' },
      body: JSON.stringify({
        loja_id: 2,
        itens: [
          { produto_master_id: 9999, quantidade: 1 },
          { produto_master_id: 8888, quantidade: 2 },
        ],
      }),
    },
  )
  const res = await handler(req, mockComItensInvalidos)
  assertEquals(res.status, 422)
  const body = await res.json()
  assertEquals(body.ok, false)
  assertEquals(Array.isArray(body.itens_invalidos), true)
  assertEquals(body.itens_invalidos.length, 2)
})

