Deno.test(
  'handler: POST /requisicao RPC retorna codigo=escopo → 403',
  async () => {
    // Edge passou na validação de escopo, mas RPC detectou escopo inválido (defense-in-depth)
    const mockRPCEscopo = {
      // deno-lint-ignore no-explicit-any
      rpc: (name: string): any => {
        if (name === 'validar_pdv_api_key') {
          return Promise.resolve({
            data: { ok: true, api_key_id: 'uuid-abc', loja_ids: [2] },
            error: null,
          })
        }
        if (name === 'criar_requisicao_pdv') {
          return Promise.resolve({
            data: { ok: false, codigo: 'escopo', erro: 'loja fora do escopo da chave' },
            error: null,
          })
        }
        return Promise.resolve({ data: null, error: null })
      },
    }
    const req = new Request(
      'https://proj.supabase.co/functions/v1/pdv-movimentacao/requisicao',
      {
        method: 'POST',
        headers: { 'x-api-key': 'pdvk_teste', 'Content-Type': 'application/json' },
        body: JSON.stringify({ loja_id: 2, itens: [{ nome_produto: 'X', quantidade: 1 }] }),
      },
    )
    const res = await handler(req, mockRPCEscopo)
    assertEquals(res.status, 403)
    const body = await res.json()
    assertEquals(body.ok, false)
    assertEquals(body.codigo, 'escopo')
  },
)

Deno.test(
  'handler: POST /requisicao RPC retorna codigo=quantidade_invalida → 422',
