    const mockQtyInvalida = {
      // deno-lint-ignore no-explicit-any
      rpc: (name: string): any => {
        if (name === 'validar_pdv_api_key') {
          return Promise.resolve({
            data: { ok: true, api_key_id: 'uuid-abc', loja_ids: [2] },
            error: null,
          })
        }
        if (name === 'criar_requisicao_pdv') {
          return Promise.resolve({
            data: {
              ok: false,
              codigo: 'quantidade_invalida',
              erro: 'quantidade(s) arredondam a 0 — use valores ≥ 0.5',
              itens_invalidos: [{ nome_produto: 'Brownie', quantidade_enviada: 0.3 }],
            },
            error: null,
          })
        }
        return Promise.resolve({ data: null, error: null })
      },
    }
    const req = new Request(
      'https://proj.supabase.co/functions/v1/pdv-movimentacao/requisicao',
      {
        method: 'POST',
        headers: { 'x-api-key': 'pdvk_teste', 'Content-Type': 'application/json' },
        // quantidade 0.3 > 0 (passa no edge) mas ROUND(0.3)=0 (rejeitado pelo RPC)
        body: JSON.stringify({ loja_id: 2, itens: [{ nome_produto: 'Brownie', quantidade: 0.3 }] }),
      },
    )
    const res = await handler(req, mockQtyInvalida)
