Deno.test(
  'handler: POST /requisicao dedupe cross-key (pmid + nome mesmo produto) → RPC retorna itens_inseridos:1',
  async () => {
    // A edge NÃO deduplica — passa ambos os itens ao RPC.
    // O RPC deduplica por lower(nome_canônico_resolvido) (FIX A) → 1 linha.
    // O mock simula o resultado pós-merge com itens_inseridos:1.
    const mockMerge = {
      // deno-lint-ignore no-explicit-any
      rpc: (name: string): any => {
        if (name === 'validar_pdv_api_key') {
          return Promise.resolve({
            data: { ok: true, api_key_id: 'uuid-abc', loja_ids: [2] },
            error: null,
          })
        }
        if (name === 'criar_requisicao_pdv') {
          // Mock simula que os 2 itens (pmid=7 resolve "Brownie" + nome_produto="Brownie")
          // foram mergeados em 1 linha com qty total
          return Promise.resolve({
            data: {
              ok: true,
              requisicao_id: 42,
              loja_solicitante: 'Momma Asa Sul',
              itens_inseridos: 1,  // 2 itens → 1 linha após merge
              data_recebimento: '2026-06-30',
            },
            error: null,
          })
        }
        return Promise.resolve({ data: null, error: null })
      },
    }
    const req = new Request(
      'https://proj.supabase.co/functions/v1/pdv-movimentacao/requisicao',
      {
        method: 'POST',
        headers: { 'x-api-key': 'pdvk_teste', 'Content-Type': 'application/json' },
        body: JSON.stringify({
          loja_id: 2,
          itens: [
            { produto_master_id: 7, quantidade: 2 },   // resolve "Brownie" no RPC
            { nome_produto: 'Brownie', quantidade: 3 }, // mesmo produto por nome
          ],
        }),
      },
    )
    const res = await handler(req, mockMerge)
    assertEquals(res.status, 200)
    const body = await res.json()
    assertEquals(body.ok, true)
    assertEquals(body.itens_inseridos, 1)
  },
)

